from AlgorithmImports import *


class ExactStrategySystem(QCAlgorithm):

    RED_DAYS_REQUIRED = 3

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.close_windows = {
            ticker: RollingWindow[float](101)
            for ticker in self.symbols
        }

        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)
        self.register_indicator(self.aapl, self.aapl_rsi, Resolution.DAILY)

        self.aapl_red_streak = 0
        self.a_lot_shares = 0
        self.b_lot_shares = 0

    def on_data(self, data: Slice):
        bars = {}

        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bar = data.bars[symbol]
                bars[ticker] = bar
                self.close_windows[ticker].add(float(bar.close))

        if len(bars) != len(self.symbols):
            return

        spy_closes = self.close_windows["SPY"]
        aapl_closes = self.close_windows["AAPL"]

        if aapl_closes.count >= 2:
            if aapl_closes[0] < aapl_closes[1]:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        if spy_closes.count < 101 or not self.aapl_rsi.is_ready:
            return

        spy_close_today = spy_closes[0]
        spy_close_yesterday = spy_closes[1]

        spy_sma_today = sum(spy_closes[i] for i in range(100)) / 100.0
        spy_sma_yesterday = sum(spy_closes[i] for i in range(1, 101)) / 100.0

        spy_crosses_above = (
            spy_close_yesterday <= spy_sma_yesterday
            and spy_close_today > spy_sma_today
        )
        spy_crosses_below = (
            spy_close_yesterday >= spy_sma_yesterday
            and spy_close_today < spy_sma_today
        )

        # Evaluate sells before buys.
        if self.a_lot_shares > 0 and spy_crosses_below:
            self.market_order(self.spy, -self.a_lot_shares)
            self.a_lot_shares = 0

        if self.b_lot_shares > 0 and self.aapl_rsi.current.value > 60:
            self.market_order(self.aapl, -self.b_lot_shares)
            self.b_lot_shares = 0

        if self.a_lot_shares == 0 and spy_crosses_above:
            shares = int((self.portfolio.total_portfolio_value * 0.40) // spy_close_today)
            if shares > 0:
                self.market_order(self.spy, shares)
                self.a_lot_shares = shares

        if (
            self.b_lot_shares == 0
            and self.aapl_red_streak >= self.RED_DAYS_REQUIRED
            and self.portfolio.cash >= 20_000
        ):
            shares = int(20_000 // bars["AAPL"].close)
            if shares > 0:
                self.market_order(self.aapl, shares)
                self.b_lot_shares = shares
